"""Abstract sensor interface. All sensors produce Detection messages."""

from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import Optional


@dataclass
class Detection:
    """Standardized detection message from any sensor."""
    sensor_id: str
    timestamp: float
    position: tuple[float, float, float]   # x, y, z (m, local NED frame)
    velocity: tuple[float, float, float]   # m/s
    confidence: float                       # 0..1
    features: dict = field(default_factory=dict)
    # features examples:
    #   rf:  {"freq_mhz": 2450, "rssi_dbm": -72, "modulation": "GFSK"}
    #   ac:  {"spl_db": 85, "bearing_deg": 120}
    #   eo:  {"bbox": [x,y,w,h], "thermal_contrast": 0.7}
    #   rad: {"rcs_m2": 0.05, "radial_vel": -12.3}


class Sensor(ABC):
    """Base class for all sensor nodes."""

    def __init__(self, node_id: str):
        self.node_id = node_id
        self._healthy = True

    @abstractmethod
    def poll(self) -> list[Detection]:
        """Return detections since last poll. Empty list if none."""
        ...

    def health(self) -> bool:
        return self._healthy

    def mark_unhealthy(self) -> None:
        self._healthy = False
        # Fusion will degrade gracefully (see SensorFusion)

